        <p id="speech-state">Speech is checking availability.</p>
        <p id="speech-preview">Choose a review card to see what will be spoken.</p>
        <div class="voice-controls" aria-label="Voice playback controls">
          <button id="read-card" type="button">Read current card</button>
          <button id="pause-resume" type="button" disabled>Pause</button>
          <button id="stop" type="button" disabled>Stop</button>
