.overview-panel, .continuation-panel, .voice-panel { margin-top: 1.5rem; padding: 1.25rem; border: 1px solid var(--line); border-radius: .55rem; background: var(--surface); }
.overview-panel h2, .continuation-panel h2, .voice-panel h2 { margin-top: 0; }
