.section-heading { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: .5rem 1rem; }
.section-heading h2 { margin-bottom: 0; }
.review-cards { display: grid; gap: 1rem; padding-left: 2rem; }
.review-card { border: 1px solid var(--line); border-left: .45rem solid var(--accent); padding: 1.1rem; background: var(--surface); }
.review-card[data-active="true"] { border-color: var(--accent-strong); box-shadow: 0 0 0 2px #9fcfbb; }
.review-card header { display: flex; justify-content: space-between; gap: .75rem; align-items: start; }
.card-controls, .voice-controls { display: flex; flex-wrap: wrap; gap: .6rem; margin-top: 1rem; }
.claim-list { padding-left: 1.25rem; }
.claim-list li { margin-block: .8rem; }
.claim-meta { color: var(--muted); font-size: .92rem; }
.source-control { margin-left: .45rem; padding: .28rem .5rem; font-size: .9rem; }
.empty-note { padding: .75rem; background: #eff3ef; border-left: .3rem solid var(--muted); }
details { margin-block: .75rem; border: 1px solid var(--line); border-radius: .35rem; padding: .7rem; background: var(--surface); }
