pre { white-space: pre-wrap; overflow-wrap: anywhere; background: #f0f3ef; padding: .8rem; border-radius: .25rem; font-size: .9rem; }
.warning { padding: .9rem; margin-block: .75rem; border-left: .35rem solid var(--warning); background: var(--warning-bg); }
