@media (max-width: 38rem) { body { font-size: 1rem; } .page-width { width: min(100% - 1.25rem, 72ch); } .target { grid-template-columns: 1fr; gap: .1rem; } .target dd { margin-bottom: .6rem; } .review-card header { display: block; } .card-controls button, .voice-controls button { width: 100%; } }
