func (f *fakeRunner) Run(_ context.Context, name string, args []string, _ string) ([]byte, []byte, error) {
	f.calls = append(f.calls, append([]string{name}, args...))
	r, ok := f.results[strings.Join(append([]string{name}, args...), " ")]
